    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": result_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    # Document order: E -> X, cancel
    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

